This question evaluates the ability to architect a real-time analytics UI with strict tenant isolation, efficient data handling, and React optimization techniques.

**Key Concepts**
- useSyncExternalStore for subscribing to external data streams
- Memoized selectors keyed by multiple dimensions (tenantId, metricId, timeWindow)
- Per-tenant data scoping with proper cleanup on tenant switch
- Real-time rendering with virtualization for large datasets
- Interactive zoom/pan handling with debouncing

**Code Sketches**

```javascript
// Stream wrapper
function createTenantStream(tenantId, metricId) {
  let subscribers = new Set();
  let currentData = [];
  let ws = null;

  const connect = () => {
    ws = new WebSocket(`/api/tenants/${tenantId}/metrics/${metricId}`);
    ws.onmessage = (e) => {
      currentData = [...currentData, JSON.parse(e.data)];
      subscribers.forEach(fn => fn(currentData));
    };
  };

  return {
    subscribe(fn) {
      subscribers.add(fn);
      if (!ws) connect();
      return () => subscribers.delete(fn);
    },
    getSnapshot() { return currentData; }
  };
}

// Memoized selector
function createMetricSelector(tenantId, metricId, timeWindow) {
  return useMemo(() => (data) => {
    const filtered = data.filter(d => 
      d.timestamp >= Date.now() - timeWindow
    );
    return downsample(filtered, 5000);
  }, [tenantId, metricId, timeWindow]);
}

// LineChart with virtualization
const LineChart = React.memo(function LineChart({ data, width, height }) {
  const canvasRef = useRef(null);
  return <canvas ref={canvasRef} width={width} height={height} />;
});

// Panel wiring
function PerTenantAnalyticsPanel({ tenantId, metricId, timeWindow }) {
  const theme = useContext(ThemeContext);
  const stream = useMemo(
    () => createTenantStream(tenantId, metricId),
    [tenantId, metricId]
  );
  const data = useSyncExternalStore(stream.subscribe, stream.getSnapshot);
  const selectMetric = createMetricSelector(tenantId, metricId, timeWindow);
  const series = selectMetric(data);

  useEffect(() => {
    return () => { /* cleanup zoom/pan state */ };
  }, [tenantId]);

  return <LineChart data={series} theme={theme} />;
}
```

## Why This Is Asked
This question tests mastery of closures, Promise coordination, and cache invalidation patterns in JavaScript without DOM dependencies.

## Key Concepts
- Closures for maintaining per-URL cache state
- Promise deduplication for concurrent in-flight requests
- Stale-while-revalidate caching strategy
- Race condition prevention and cache lifecycle management

## Code Example
```javascript
function makeFetcher() {
  const cache = new Map();
  return {
    fetchMemo: (url, ttlMs) => {
      const getEntry = () => cache.get(url) || { value: null, ts: 0, inFlight: null };
      const fetchAndUpdate = async () => {
        try {
          const response = await fetch(url);
          const data = await response.json();
          cache.set(url, { value: data, ts: Date.now(), inFlight: null });
          return data;
        } catch (error) {
          const entry = getEntry();
          entry.inFlight = null;
          throw error;
        }
      };

      return {
        get: async () => {
          const entry = getEntry();
          const now = Date.now();
          const isFresh = entry.value && (now - entry.ts) < ttlMs;

          if (isFresh) return entry.value;

          if (entry.inFlight) {
            await entry.inFlight;
            return getEntry().value;
          }

          if (entry.value) {
            entry.inFlight = fetchAndUpdate();
            return entry.value;
          }

          entry.inFlight = fetchAndUpdate();
          return await entry.inFlight;
        },
        invalidate: () => cache.delete(url)
      };
    }
  };
}
```

## Demonstration
```javascript
const fetcher = makeFetcher();

// Set up two URLs with different TTLs
const api1 = fetcher.fetchMemo('https://api.example.com/data1', 5000);
const api2 = fetcher.fetchMemo('https://api.example.com/data2', 10000);

// Concurrent callers will observe stale data immediately while fresh data loads in background
```

